function showPanel(panel){
  document.querySelectorAll('.eg-panel').forEach(item=>item.classList.toggle('active',item===panel));
  document.querySelectorAll('.eg-tab').forEach(tab=>{const active=tab.dataset.tab==='lost';tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active));if(active)tab.setAttribute('aria-current','page');else tab.removeAttribute('aria-current')});
  document.querySelectorAll('.elma-main-tab').forEach(tab=>{const active=tab.dataset.elmaTab==='lost';tab.classList.toggle('active',active);if(active)tab.setAttribute('aria-current','page');else tab.removeAttribute('aria-current')});
  $('.hero')?.style.setProperty('display','none');$('.mapwrap')?.style.setProperty('display','none');$('#elmaHomeWidgets')?.classList.remove('home-active');
}
function goServices(){const mainTab=document.querySelector('.elma-main-tab[data-elma-tab="services"]');if(mainTab){mainTab.click();return}if(window.elmaSelectMainTab)window.elmaSelectMainTab('services');else{const panel=$('.eg-panel[data-panel="services"]');if(panel){document.querySelectorAll('.eg-panel').forEach(item=>item.classList.toggle('active',item===panel));document.querySelector('.eg-tab[data-tab="services"]')?.classList.add('active')}}}
function toast(text,error=false){const node=$('#egLostToast');if(!node)return;node.textContent=text;node.classList.toggle('error',error);node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),3200)}
function setStatus(text,error=false){const node=$('#egLostStatus');if(node){node.textContent=text;node.classList.toggle('error',error)}}
function maskedOwnerName(account){const raw=String(account?.displayName||account?.email?.split('@')[0]?.replace(/[._-]+/g,' ')||'').trim(),parts=raw.split(/\s+/).filter(Boolean);if(!parts.length)return'Elma Go kullanıcısı';if(parts.length===1)return parts[0]+' *';const surname=parts.at(-1),stars='*'.repeat(Math.max(2,Math.min(8,surname.length-1)));return parts[0]+' '+surname.charAt(0).toLocaleUpperCase('tr-TR')+stars}
function position(){if(window.elmaUserPosition)return Promise.resolve(window.elmaUserPosition);return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('Konum desteklenmiyor.'));navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,timeout:15000,maximumAge:300000})})}
async function resolveViewerCity(){viewerCity=FIXED_CITY;try{localStorage.setItem('elmaViewerCity',FIXED_CITY)}catch{}viewerCoords=null;viewerDistrict='';setStatus('Amasya ilanları gösteriliyor.');return viewerCity}

async function connectFirebase(){
  if(api){if(!viewerCity){cityResolution=null;await resolveViewerCity();if(viewerCity)subscribeListings()}return api}
  const [appModule,authModule,dbModule,storageModule]=await Promise.all([import(FIREBASE.app),import(FIREBASE.auth),import(FIREBASE.db),import(FIREBASE.storage)]);
  for(let i=0;i<30&&!appModule.getApps().length;i++)await new Promise(resolve=>setTimeout(resolve,50));
  const app=appModule.getApps()[0]||appModule.initializeApp(APP_CONFIG);
  const auth=authModule.getAuth(app),db=dbModule.getFirestore(app),storage=storageModule.getStorage(app);
  api={...authModule,...dbModule,...storageModule,auth,db,storage};
  authModule.onAuthStateChanged(auth,next=>{if(user?.uid!==next?.uid){closeChat();clearConversationWatchers();clearCryptoCache()}user=next;if(next)ensureE2EEIdentity(next).catch(()=>{});chatSeen=readChatSeen();subscribeBlocks();subscribePrivateListings();subscribeRequests();subscribeOutgoingRequests();subscribeMyListings();render();prefillUser()});
  await resolveViewerCity();if(viewerCity)subscribeListings();return api;
}
function subscribeListings(){
  if(!api||!viewerCity||unsubscribeListings)return;
  const source=api.query(api.collection(api.db,'lostFoundListings'),api.where('city','==',viewerCity),api.where('status','==','active'),api.limit(100));
  unsubscribeListings=api.onSnapshot(source,snapshot=>{if(listingSnapshotReady)snapshot.docChanges().filter(change=>change.type==='added').forEach(change=>notifyNearbyListing({id:change.doc.id,...change.doc.data()}));listings=snapshot.docs.map(doc=>({id:doc.id,...doc.data()})).sort((a,b)=>(dateValue(b.createdAt)||0)-(dateValue(a.createdAt)||0));listingSnapshotReady=true;setStatus(viewerCity+' ilanları gösteriliyor.');render();checkMatches()},error=>setStatus(error.code==='permission-denied'?'İlanları görüntülemek için veritabanı izni gerekli.':'İlanlar şu anda alınamadı.',true));
}
function subscribeMyListings(){unsubscribeMine?.();unsubscribeMine=null;myListings=[];if(!api||!user){updateAccountSummary();return}const source=api.query(api.collection(api.db,'lostFoundListings'),api.where('ownerUid','==',user.uid),api.limit(100));unsubscribeMine=api.onSnapshot(source,snapshot=>{myListings=snapshot.docs.map(doc=>({id:doc.id,...doc.data()}));updateAccountSummary();render();checkMatches()},()=>updateAccountSummary())}
function subscribeRequests(){
  unsubscribeRequests?.();unsubscribeRequests=null;requests=[];
  if(!api||!user){render();return}
  const source=api.query(api.collection(api.db,'lostFoundContacts'),api.where('ownerUid','==',user.uid));
  unsubscribeRequests=api.onSnapshot(source,snapshot=>{requests=snapshot.docs.map(doc=>({id:doc.id,...doc.data()})).sort((a,b)=>(dateValue(b.createdAt)||0)-(dateValue(a.createdAt)||0));syncConversationWatchers();render();updateAccountSummary();updateUnreadBadges()},()=>{});
}
function subscribeOutgoingRequests(){unsubscribeOutgoing?.();unsubscribeOutgoing=null;outgoingRequests=[];if(!api||!user){syncConversationWatchers();render();updateAccountSummary();updateUnreadBadges();return}const source=api.query(api.collection(api.db,'lostFoundContacts'),api.where('requesterUid','==',user.uid));unsubscribeOutgoing=api.onSnapshot(source,snapshot=>{outgoingRequests=snapshot.docs.map(doc=>({id:doc.id,...doc.data()})).sort((a,b)=>(dateValue(b.createdAt)||0)-(dateValue(a.createdAt)||0));syncConversationWatchers();render();updateAccountSummary();updateUnreadBadges()},()=>{})}
function readChatSeen(){if(!user)return{};try{return JSON.parse(localStorage.getItem('elmaChatSeen_'+user.uid)||'{}')}catch{return{}}}
function saveChatSeen(){if(!user)return;try{localStorage.setItem('elmaChatSeen_'+user.uid,JSON.stringify(chatSeen))}catch{}}
function conversationReadKey(request){return conversationLatest.get(request.id)?.id||'request:'+request.id}
function isConversationUnread(request){if(!user||request.status==='rejected'||isConversationBlocked(request))return false;const latest=conversationLatest.get(request.id);if(latest)return latest.senderUid!==user.uid&&chatSeen[request.id]!==latest.id;return request.ownerUid===user.uid&&chatSeen[request.id]!==conversationReadKey(request)}
function markConversationRead(request){if(!request?.id)return;chatSeen[request.id]=conversationReadKey(request);saveChatSeen();updateUnreadBadges();if(mode==='requests')render()}
function ensureUnreadBadge(host,id){if(!host)return null;let badge=host.querySelector('#'+id);if(!badge){badge=document.createElement('span');badge.id=id;badge.className='eg-chat-badge';badge.hidden=true;host.appendChild(badge)}return badge}
function updateUnreadBadges(){const all=[...requests,...outgoingRequests].filter((item,index,array)=>item.status!=='rejected'&&array.findIndex(other=>other.id===item.id)===index),count=all.filter(isConversationUnread).length,labels=[ensureUnreadBadge($('.eg-lost-card'),'egLostCardBadge'),ensureUnreadBadge($('.eg-lost-nav button[data-mode="requests"]'),'egLostMessagesBadge'),ensureUnreadBadge(document.querySelector('.eg-tab[data-tab="lost"]'),'egLostTabBadge'),ensureUnreadBadge(document.querySelector('.elma-main-tab[data-elma-tab="lost"]'),'elmaLostMainTabBadge')];labels.forEach(badge=>{if(!badge)return;badge.hidden=!count;badge.textContent=count>9?'9+':String(count)});document.title=count?'('+count+') ElmaGo':'ElmaGo'}
function clearConversationWatchers(){conversationWatchers.forEach(stop=>stop());conversationWatchers.clear();conversationLatest.clear();updateUnreadBadges()}
function syncConversationWatchers(){
  if(!api||!user)return clearConversationWatchers();
  const accountUid=user.uid,all=[...requests,...outgoingRequests].filter((item,index,array)=>item.status!=='rejected'&&!isConversationBlocked(item)&&array.findIndex(other=>other.id===item.id)===index).sort((a,b)=>(dateValue(b.createdAt)||0)-(dateValue(a.createdAt)||0)).slice(0,30),ids=new Set(all.map(item=>item.id));
  conversationWatchers.forEach((stop,id)=>{if(!ids.has(id)){stop();conversationWatchers.delete(id);conversationLatest.delete(id)}});
  all.forEach(request=>{
    if(conversationWatchers.has(request.id))return;
    let ready=false,revision=0;
    // A closed conversation needs one preview, not 100 decryptions and receipt writes.
    const source=api.query(api.collection(api.db,'lostFoundContacts',request.id,'messages'),api.orderBy('createdAt','desc'),api.limit(1));
    const stop=api.onSnapshot(source,async snapshot=>{
      const generation=++revision,messages=snapshot.docs.map(doc=>({id:doc.id,...doc.data()})),latest=messages[0],previous=conversationLatest.get(request.id);
      const preview=latest?(latest.encryption?await decryptMessage(request,latest):latest.text):null;
      if(user?.uid!==accountUid||isConversationBlocked(request)||!conversationWatchers.has(request.id)||generation!==revision)return;
      if(latest)conversationLatest.set(request.id,{...latest,text:preview});else conversationLatest.delete(request.id);
      await acknowledgeMessages(request,messages);
      if(currentChat?.id===request.id)markConversationRead(request);
      else{updateUnreadBadges();if(mode==='requests')render();if(ready&&latest&&latest.id!==previous?.id&&latest.senderUid!==accountUid)toast('Yeni mesajın var.')}
      ready=true;
    },()=>{});
    conversationWatchers.set(request.id,stop);
  });updateUnreadBadges();
}
function filteredItems(){
  const source=mode==='mine'?myListings:listings;return source.filter(item=>{
    if(mode!=='mine'&&(!viewerCity||cityKey(itemCity(item))!==cityKey(viewerCity)))return false;
    if(blockedOwners.has(item.ownerUid))return false;
    if(mode==='lost'&&item.kind!=='lost'||mode==='found'&&item.kind!=='found'||mode==='mine'&&item.ownerUid!==user?.uid)return false;
    if(mode!=='mine'&&!activeListing(item)||category!=='all'&&item.category!==category)return false;
    if(mode!=='mine'&&nearOnly&&distanceKm(viewerCoords,item.coords)>5)return false;
    const haystack=normalize([item.title,item.description,item.location,item.district,item.address,item.category,item.ownerName].join(' '));
    return !query||haystack.includes(query);
  });
}
